mapper.update:
UPDATE career_application_record
SET deleted = 1,
    update_time = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted = 0

mapper.select:
SELECT 
FROM career_application_record
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted = 0

SELECT FROM career_application_record WHERE user_id = #{userId} AND deleted = 0
AND status = #{status}
ORDER BY CASE WHEN next_follow_up_date IS NULL THEN 1 ELSE 0 END ASC, next_follow_up_date ASC, update_time DESC, id DESC

SELECT 
FROM career_application_record
WHERE user_id = #{userId}

    AND (update_time > #{afterUpdateTime}
        OR (update_time = #{afterUpdateTime} AND id >= #{afterSourceId}))

ORDER BY update_time ASC, id ASC
LIMIT #{limit}

SELECT user_id
FROM career_application_record
WHERE update_time >= #{updatedAfter}
GROUP BY user_id
ORDER BY MAX(update_time) DESC, user_id ASC
LIMIT #{limit}
